<script lang="ts">import { onMount } from 'svelte';import { clearNote,loadNote,saveNote } from '$lib/utils/storage';let { chapterId }:{chapterId:string}=$props();let value=$state('');let status=$state('Saved only on this device');let key=$derived(`alienFieldGuide.chapter.${chapterId}.privateNote`);onMount(()=>value=loadNote(key));function save(){status=saveNote(key,value)?'Saved only on this device':'Could not save on this device'}function clear(){value='';clearNote(key);status='Field note cleared'}</script>
<section class="private-note"><p class="eyebrow">Your private field note</p><h2>Now that you can see more of the field, what might you say next?</h2><p>This optional note stays in this browser. It is not transmitted to Earth authorities, school administrators, or Zee’s supervisors.</p><label for="field-note">Your observation</label><textarea id="field-note" rows="4" placeholder="I noticed…" bind:value oninput={save}></textarea><div><span aria-live="polite">{status}</span><button onclick={clear}>Clear my field note</button></div></section>
